CREATE TYPE "GuestInvitationStatus" AS ENUM ('NOT_SENT','SENT','DELIVERED','FAILED');
CREATE TABLE "Guest" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"name" VARCHAR(160) NOT NULL,"email" VARCHAR(254),"phone" VARCHAR(30),"category" VARCHAR(80),"notes" VARCHAR(1000),"invitationCode" VARCHAR(64) NOT NULL,"plusOneAllowed" BOOLEAN NOT NULL DEFAULT false,"maxGuests" INTEGER NOT NULL DEFAULT 1,"invitationStatus" "GuestInvitationStatus" NOT NULL DEFAULT 'NOT_SENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Guest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Guest_invitationCode_key" ON "Guest"("invitationCode"); CREATE INDEX "Guest_eventId_name_idx" ON "Guest"("eventId","name"); CREATE INDEX "Guest_eventId_invitationStatus_idx" ON "Guest"("eventId","invitationStatus"); ALTER TABLE "Guest" ADD CONSTRAINT "Guest_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE;
